interface ToothChartSvgProps {
  presentTeeth?: number[] // Array of tooth IDs that are present
  className?: string
}


export function ToothChartSvg({ presentTeeth = [], className }: ToothChartSvgProps) {
  // Function to determine if a tooth is present
  const isPresent = (toothId: number) => presentTeeth.includes(toothId)

  return (
    <div className={cn("relative w-full bg-gray-900 rounded-lg p-4", className)}>
      <h3 className="text-white text-sm font-medium mb-2 flex items-center justify-between">
        <span>Tooth Chart</span>
        <div className="flex items-center gap-4 text-xs">
          <div className="flex items-center gap-1">
            <div className="w-3 h-3 bg-green-500 rounded-sm"></div>
            <span>Present</span>
          </div>
          <div className="flex items-center gap-1">
            <div className="w-3 h-3 bg-red-500 rounded-sm"></div>
            <span>Missing</span>
          </div>
        </div>
      </h3>

      <div className="relative w-full overflow-x-auto">
        <svg width="450" height="190" viewBox="0 0 450 190" className="mx-auto">
          {TEETH_DATA.map((tooth) => (
            <g key={tooth.id} transform={`translate(${tooth.x}, ${tooth.y})`}>
              {/* Tooth number label - positioned above for upper teeth, below for lower teeth */}
              <text
                x={tooth.width ? tooth.width / 2 : 7.5}
                y={tooth.isUpper ? -8 : tooth.height ? tooth.height + 15 : 45}
                textAnchor="middle"
                fill="white"
                fontSize="10"
                fontWeight="bold"
              >
                {tooth.id}
              </text>
                <svg
                  width={tooth.width}
                  height={tooth.height}
                  viewBox={tooth.viewBox}
                  // preserveAspectRatio="xMidYMid meet"
                >
                  {tooth.svgPath.map((path, index) => (
                    <path
                      key={index}
                      d={path}
                      fill={isPresent(tooth.id) ? "#22c55e" : "#ef4444"}
                      // className="transition-colors duration-300"
                    />
                  ))}
                </svg>
            </g>
          ))}

          {/* Add jaw line indicators */}
          <line x1="5" y1="90" x2="455" y2="90" stroke="#555" strokeWidth="1" strokeDasharray="5,5" />
          </svg>
      </div>
    </div>
  )
}
